#include <chrono>
static int compute(int d) {
  for (int c = 0; c < 10; c++) d = d * d / 42;
  return d;
}
void bench_wrong(int x, long n) {
  auto t0 = std::chrono::steady_clock::now();
  for (long i = 0; i < n; i++) compute(x);   // result ignored
  auto t1 = std::chrono::steady_clock::now();
  // report (t1 - t0) / n as "ns per call"
}

int bench_fold(long n) {
  int s = 0;
  for (long i = 0; i < n; i++) s += compute(42);
  return s;
}
// clang -O2, x86-64:
//   imul  ecx, edi, 42   ; s = 42 * n
//   xor   eax, eax
//   test  rdi, rdi
//   cmovg eax, ecx       ; 0 if n <= 0
//   ret

template <class T>
inline __attribute__((always_inline)) void DoNotOptimize(T& v) {
  // Emits no instruction. Tells the compiler: this asm may read and
  // overwrite v, and may read or write any memory.
  asm volatile("" : "+r,m"(v) : : "memory");
}

static void BM_compute(benchmark::State& state) {
  int x = 41;
  for (auto _ : state) {
    benchmark::DoNotOptimize(x);
    int r = compute(x);
    benchmark::DoNotOptimize(r);
  }
}
BENCHMARK(BM_compute);
